     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.LocalDate;
     4	import java.time.Period;
     5	
     6	import org.springframework.samples.petclinic.model.Owner;
     7	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
     8	
     9	/**
    10	 * Derives an owner's {@link OwnerDto.AgeBandEnum age band} from the birthDate, computed as
    11	 * the owner's age on the registrationDate: MINOR when under 18, ADULT when 18 to 64, SENIOR
    12	 * when 65 or over. Returns {@code null} when no birthDate was supplied, so the field is
    13	 * absent from the response.
    14	 */
    15	public final class AgeBand {
    16	
    17	    private AgeBand() {
    18	    }
    19	
    20	    public static OwnerDto.AgeBandEnum of(Owner owner) {
    21	        LocalDate birthDate = owner.getBirthDate();
    22	        if (birthDate == null) {
    23	            return null;
    24	        }
    25	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
    26	        int age = Period.between(birthDate, reference).getYears();
    27	        if (age < 18) {
    28	            return OwnerDto.AgeBandEnum.MINOR;
    29	        }
    30	        if (age < 65) {
    31	            return OwnerDto.AgeBandEnum.ADULT;
    32	        }
    33	        return OwnerDto.AgeBandEnum.SENIOR;
    34	    }
    35	}

