     1	package org.springframework.samples.petclinic.rest.function.common;
     2	
     3	/**
     4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
     5	 * characters are ignored, so a value such as {@code NSW-1A2B3C4D} is treated as its
     6	 * digit sequence {@code 1234}. Doubling starts from the rightmost digit, matching the
     7	 * standard Luhn convention for a bare (un-appended) payload.
     8	 */
     9	public final class Luhn {
    10	
    11	    private Luhn() {
    12	    }
    13	
    14	    /**
    15	     * The Luhn check digit (0-9) over the digits contained in {@code s}, or {@code 0}
    16	     * when {@code s} is null or holds no digits.
    17	     */
    18	    public static int checkDigit(String s) {
    19	        if (s == null) {
    20	            return 0;
    21	        }
    22	        int sum = 0;
    23	        boolean dbl = true;
    24	        for (int i = s.length() - 1; i >= 0; i--) {
    25	            char c = s.charAt(i);
    26	            if (c < '0' || c > '9') {
    27	                continue;
    28	            }
    29	            int d = c - '0';
    30	            if (dbl) {
    31	                d *= 2;
    32	                if (d > 9) {
    33	                    d -= 9;
    34	                }
    35	            }
    36	            sum += d;
    37	            dbl = !dbl;
    38	        }
    39	        return (10 - (sum % 10)) % 10;
    40	    }
    41	}

